CIB_MODS.register('simple-timestamp-mod', {
  meta: {
    name: 'Simple Timestamp Mod',
    creator: 'jxburros',
    version: '1.0.0',
    type: 'Plugin'
  },
  onAppInit(ctx) {
    console.log('[SimpleTimestampMod] Initialized');
    ctx.api.showToast('Simple Timestamp Mod loaded', 'success');
  },
  onCardRender(ctx, cardId, cardElement) {
    const card = ctx.api.getCard(cardId);
    if (!card) return;

    const timestamp = card.updatedAt || card.createdAt;
    if (!timestamp) return;

    const date = new Date(timestamp);
    const timeStr = date.toLocaleString();

    const timestampDiv = document.createElement('div');
    timestampDiv.style.cssText = 'color: var(--text-muted); font-size: var(--text-xs); margin-top: var(--space-sm); font-style: italic;';
    timestampDiv.textContent = 'Last updated: ' + timeStr;

    const detailSection = cardElement.querySelector('.card-detail, .card-body');
    if (detailSection) {
      detailSection.appendChild(timestampDiv);
    }
  }
});

